namespace ghidra.app.plugin.core.datamgr.tree;






using org.apache.commons.lang3;

using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr.util;
using ghidra.app.util;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util;
using ghidra.util.exception;

public class DataTypeNode : DataTypeTreeNode {
	private DataType dataType;
	private string name;
	private string displayText;

	private bool isCut;
	private bool useHighlight = false;

	private string toolTipText;
	// records the root node's mod count at the last time we computed the tooltip text.
	private long lastModCount;

	public DataTypeNode(DataType dataType) {
		this.dataType = dataType;
		this.name = dataType.getName();
		this.displayText = getCurrentDisplayText();
	}

	/* @Override */
	public int compareTo(GTreeNode node) {
		if (node is DataTypeNode other) {
			return DataTypeNameComparator.INSTANCE.compare(dataType.getName(),
				other.dataType.getName());
		}

		return 1; // DataTypeNodes always come after ****everything else****
	}

	public DataType getDataType() {
		return dataType;
	}

	/* @Override */
	public bool equals(object o) {
		if (this == o) {
			return true;
		}
		if (getClass() != o.GetType()) {
			return false;
		}

		DataTypeNode otherNode = (DataTypeNode) o;
		CategoryPath otherPath = otherNode.getDataType().getCategoryPath();
		CategoryPath path = dataType.getCategoryPath();
		if (!path.equals(otherPath)) {
			return false;
		}
		return name.equals(otherNode.name);
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		if (isFavorite()) {
			return DataTypeUtils.getFavoriteIcon(isCut);
		}

		Icon icon = null;
		if (dataType is BuiltInDataType) {
			icon = DataTypeUtils.getBuiltInIcon(isCut);
		}
		else {
			icon = DataTypeUtils.getIconForDataType(dataType, isCut);
		}

		if (!isCut && useHighlight) {
			return DataTypeUtils.getHighlightIcon(icon);
		}

		return icon;
	}

	/* @Override */
	public string getName() {
		return name;
	}

	/* @Override */
	public string getToolTip() {
		if (archiveChanged()) {
			toolTipText = null;
		}

		if (toolTipText == null) {
			toolTipText = ToolTipUtils.getToolTipText(dataType);
		}

		return toolTipText;
	}

	private bool archiveChanged() {
		GTreeNode root = getRoot();
		if (root is ArchiveRootNode archiveRootNode) {
			long modCount = archiveRootNode.getModificationCount();
			if (lastModCount == modCount) {
				return false;
			}
			lastModCount = modCount;
			return true;
		}
		return false;
	}

	/* @Override */
	public bool isLeaf() {
		return true;
	}

	/* @Override */
	public void valueChanged(object newValue) {
		if (dataType.getName().equals(newValue)) {
			return;
		}

		string newName = newValue.toString();
		if (StringUtils.isBlank(newName)) {
			Msg.showError(getClass(), null, "Rename Failed", "Name cannot be empty.");
			return;
		}

		int transactionID = dataType.getDataTypeManager().startTransaction("Rename DataType");

		try {
			dataType.setName(newName);
		}
		catch (DuplicateNameException e) {
			Msg.showError(getClass(), null, "Rename Failed",
				"Data Type by the name " + newValue + " already exists in this category.");
		}
		catch (InvalidNameException exc) {
			string msg = exc.getMessage();
			if (msg == null) {
				msg = "Invalid name specified: " + newValue;
			}
			Msg.showError(getClass(), null, "Invalid Name Specified", exc.getMessage());
		}
		finally {
			dataType.getDataTypeManager().endTransaction(transactionID, true);
		}
	}

	/* @Override */
	public bool isEditable() {
		return isModifiable() && canRename();
	}

	/**
	 * Returns true if this dataType node uses and editor that is different than Java's default
	 * editor.
	 * 
	 * @return true if this dataType node has a custom editor.
	 */
	public bool hasCustomEditor() {
		return (dataType is Composite) || (dataType is Enum) ||
			(dataType is FunctionDefinition) || hasCustomEditorForBaseDataType();
	}

	private bool hasCustomEditorForBaseDataType() {
		DataType baseDataType = DataTypeUtils.getBaseDataType(dataType);
		return (baseDataType is Composite) ||
			(baseDataType is Enum || (dataType is FunctionDefinition));
	}

	private bool canRename() {
		return !(dataType is BuiltInDataType ||
			dataType is MissingBuiltInDataType || dataType is Array ||
			dataType is Pointer);
	}

	/* @Override */
	public string toString() {
		return getName();
	}

	public bool isFavorite() {
		DataTypeManager dataTypeManager = dataType.getDataTypeManager();
		return dataTypeManager.isFavorite(dataType);
	}

	/* @Override */
	public void setNodeCut(bool isCut) {
		this.isCut = isCut;
		fireNodeChanged();
	}

	/* @Override */
	public bool canCut() {
		return isModifiable();
	}

	/* @Override */
	public bool canPaste(List<GTreeNode> pastedNodes) {
		return isModifiable();
	}

	/* @Override */
	public bool isCut() {
		return isCut;
	}

	/* @Override */
	public DataTypeStoreNode getArchiveNode() {
		GTreeNode parent = getParent();
		if (parent == null) {
			return null; // could happen during tree mutations
		}

		return ((DataTypeTreeNode) parent).getArchiveNode();
	}

	/* @Override */
	public bool isModifiable() {
		DataTypeStoreNode archiveNode = getArchiveNode();
		return archiveNode != null && archiveNode.isModifiable();
	}

	/* @Override */
	public bool canDelete() {
		return true;
	}

	public void dataTypeStatusChanged() {
		fireNodeChanged();
	}

	public void dataTypeChanged() {
		toolTipText = null;
		fireNodeChanged();
		GTree tree = getTree();
		if (tree != null) {
			tree.repaint(); // need to repaint in case related datatypes changes mod status.
		}
	}

	/* @Override */
	public string getDisplayText() {
		// note: we have to check the name each time, as the optional underlying
		//       source archive may have changed.
		string currentDisplayText = getCurrentDisplayText();
		if (!displayText.equals(currentDisplayText)) {
			displayText = currentDisplayText;
			fireNodeChanged();
		}
		return displayText;
	}

	private string getCurrentDisplayText() {

		string baseDisplayText = dataType.getName();

		UniversalID localID = dataType.getDataTypeManager().getUniversalID();
		SourceArchive sourceArchive = dataType.getSourceArchive();
		if (sourceArchive != null && sourceArchive.getArchiveType() != ArchiveType.BUILT_IN &&
			!sourceArchive.getSourceArchiveID().equals(localID)) {
			return baseDisplayText + "  (" + sourceArchive.getName() + ")";
		}

		return baseDisplayText;
	}

	/* @Override */
	protected List<GTreeNode> generateChildren() {
		return Collections.emptyList();
	}
}
